      I[x] += I_ref[x] + I_sc[x]
      F[x] += I0_j

    // Normalize the radiation intensity and fluence arrays
    I /= sum(I)
    F /= sum(F)

  // Return the final radiation intensity and fluence arrays
  return I, F
